{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "T_bounds",
      "expression": "1 <= T <= 10",
      "description": "The number of test cases is between 1 and 10, inclusive."
    },
    {
      "id": "MN_bounds",
      "expression": "0 <= M, N <= 10^6",
      "description": "The values of M and N are between 0 and 10^6, inclusive."
    },
    {
      "id": "string_length_bounds",
      "expression": "1 <= len(string) <= 10^6",
      "description": "The length of the string is between 1 and 10^6 characters, inclusive."
    },
    {
      "id": "string_characters",
      "expression": "all(char in ['R', 'K'] for char in string)",
      "description": "The string consists only of characters 'R' and 'K'."
    }
  ],
  "postconditions": [
    {
      "id": "output_format",
      "expression": "output == [[int, int] for _ in range(T)]",
      "description": "The output is a list of pairs of integers, one for each test case."
    },
    {
      "id": "output_values",
      "expression": "all(output[i][0] == count_MR(test_cases[i][1], M) and output[i][1] == count_NK(test_cases[i][1], N) for i in range(T))",
      "description": "The first integer in the output is the number of substrings containing exactly M 'R' characters, and the second integer is the number of substrings containing exactly N 'K' characters."
    }
  ],
  "invariants": []
}
